SELECT T.ID, T.NOME, COUNT(DISTINCT V.ID) QTD, COUNT(DISTINCT V.CANAL_ID) CANAIS, MAX(L.GERADO_EM) GERADO_EM FROM TEMAS T JOIN VIDEO_TEMAS VT ON VT.TEMA_ID = T.ID JOIN VIDEOS V ON V.ID = VT.VIDEO_ID AND V.STATUS = 'ESTUDADO' LEFT JOIN LIVRO_CAPITULOS L ON L.TEMA_ID = T.ID WHERE T.NOME NOT LIKE 'mentor: %' GROUP BY T.ID, T.NOME HAVING QTD >= 5 ORDER BY QTD DESC LIMIT 400